begin;
create table public.profiles(id uuid primary key references auth.users on delete cascade,name text not null default 'Seller',role text not null default 'seller' check(role in ('seller','admin')),phone text not null default '',payment_method text not null default 'Contact seller',payment_instructions text not null default '',suspended boolean not null default false,created_at timestamptz not null default now());
create table public.listings(id uuid primary key default gen_random_uuid(),seller_id uuid not null references public.profiles,title text not null check(length(title) between 3 and 120),description text not null default '',price numeric not null check(price>0),negotiable boolean not null default false,category text not null,location text not null,condition text not null check(condition in ('New','Used')),images text[] not null check(cardinality(images) between 1 and 5),status text not null default 'active' check(status in ('active','sold','removed')),created_at timestamptz not null default now());
create index on public.listings(status,created_at desc);create index on public.listings(seller_id);
create table public.settings(id integer primary key check(id=1),data jsonb not null);
insert into public.settings values(1,'{"site_name":"MAU Connect","hero_title":"Great finds.\nCloser connections.","hero_subtitle":"Buy what you love. Sell what you don’t. Connect with people across Nigeria.","payment_mode":"seller","payment_instructions":"","categories":["Phones & Tablets","Electronics","Fashion","Home & Living","Vehicles","Property","Beauty & Care","Sports & Outdoors"]}');
create table public.audit_log(id uuid primary key default gen_random_uuid(),actor_id uuid not null references public.profiles,action text not null,details jsonb not null,created_at timestamptz not null default now());
create table public.reports(id uuid primary key default gen_random_uuid(),listing_id uuid references public.listings,reporter_id uuid references public.profiles,reason text not null check(length(reason) between 3 and 1000),status text default 'open' check(status in ('open','resolved')),created_at timestamptz default now());
create function public.on_signup() returns trigger language plpgsql security definer set search_path=public as $$begin insert into public.profiles(id,name) values(new.id,left(coalesce(new.raw_user_meta_data->>'name','Seller'),80));return new;end;$$;
create trigger signup after insert on auth.users for each row execute function public.on_signup();
create function public.is_admin() returns boolean language sql stable security definer set search_path=public as $$select exists(select 1 from profiles where id=auth.uid() and role='admin' and not suspended);$$;
create function public.is_active() returns boolean language sql stable security definer set search_path=public as $$select exists(select 1 from profiles where id=auth.uid() and not suspended);$$;
alter table public.profiles enable row level security;alter table public.listings enable row level security;alter table public.settings enable row level security;alter table public.audit_log enable row level security;alter table public.reports enable row level security;
create policy profile_read on public.profiles for select to authenticated using(id=auth.uid() or public.is_admin());
create policy profile_edit on public.profiles for update to authenticated using(id=auth.uid() and public.is_active()) with check(id=auth.uid());
revoke update on public.profiles from anon,authenticated;grant update(name,phone,payment_method,payment_instructions) on public.profiles to authenticated;
create policy listing_read on public.listings for select using((status='active' and exists(select 1 from public.profiles p where p.id=listings.seller_id and not p.suspended)) or seller_id=auth.uid() or public.is_admin());
-- Security-definer visibility avoids exposing seller profile/payment data publicly.
create function public.seller_active(seller uuid) returns boolean language sql stable security definer set search_path=public as $$select exists(select 1 from profiles where id=seller and not suspended);$$;
drop policy listing_read on public.listings;
create policy listing_read on public.listings for select using((status='active' and public.seller_active(seller_id)) or seller_id=auth.uid() or public.is_admin());
create policy listing_insert on public.listings for insert to authenticated with check(seller_id=auth.uid() and public.is_active() and status='active');
create policy listing_edit on public.listings for update to authenticated using(seller_id=auth.uid() and public.is_active() and status<>'removed') with check(seller_id=auth.uid() and status in ('active','sold'));
revoke update on public.listings from authenticated;grant update(title,description,price,negotiable,category,location,condition,images,status) on public.listings to authenticated;
create policy settings_read on public.settings for select using(true);
create policy audit_read on public.audit_log for select to authenticated using(public.is_admin());
create policy report_insert on public.reports for insert to authenticated with check(reporter_id=auth.uid() and public.is_active());
create policy report_read on public.reports for select to authenticated using(public.is_admin());
create function public.seller_contact(seller uuid) returns jsonb language plpgsql security definer set search_path=public as $$declare result jsonb;begin if auth.uid() is null or not public.is_active() then raise exception 'Sign in required';end if;select jsonb_build_object('name',name,'phone',phone,'payment_method',payment_method,'payment_instructions',payment_instructions) into result from profiles where id=seller and not suspended;return result;end;$$;
create function public.admin_action(action text,payload jsonb) returns jsonb language plpgsql security definer set search_path=public as $$declare result jsonb;target uuid;begin
if not public.is_admin() then raise exception 'Admin access required';end if;
if action='remove' then update listings set status='removed' where id=(payload->>'id')::uuid;
elsif action='suspend' then target:=(payload->>'id')::uuid;if target=auth.uid() then raise exception 'Cannot suspend yourself';end if;update profiles set suspended=(payload->>'suspended')::boolean where id=target and role<>'admin';
elsif action='settings' then if payload->'settings'->>'payment_mode' not in ('seller','platform') then raise exception 'Invalid payment mode';end if;if jsonb_typeof(payload->'settings'->'categories')<>'array' then raise exception 'Categories must be an array';end if;update settings set data=payload->'settings' where id=1;
elsif action='impersonate' then if length(trim(coalesce(payload->>'reason','')))<5 then raise exception 'A support reason is required';end if;target:=(payload->>'id')::uuid;select jsonb_build_object('seller',(select to_jsonb(p)-'role' from profiles p where id=target),'listings',coalesce((select jsonb_agg(l) from listings l where seller_id=target),'[]'::jsonb),'expires_at',now()+interval '15 minutes') into result;
elsif action='reports' then select coalesce(jsonb_agg(r),'[]'::jsonb) into result from reports r;
elsif action='resolve' then update reports set status='resolved' where id=(payload->>'id')::uuid;
else raise exception 'Unsupported action';end if;
insert into audit_log(actor_id,action,details) values(auth.uid(),action,payload-'settings');return coalesce(result,'{"ok":true}'::jsonb);end;$$;
revoke all on function public.admin_action(text,jsonb),public.seller_contact(uuid) from public,anon;grant execute on function public.admin_action(text,jsonb),public.seller_contact(uuid) to authenticated;
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('listings','listings',true,5242880,array['image/jpeg','image/png','image/webp']);
create policy listing_images_read on storage.objects for select using(bucket_id='listings');
create policy listing_images_upload on storage.objects for insert to authenticated with check(bucket_id='listings' and (storage.foldername(name))[1]=auth.uid()::text and public.is_active());
create policy listing_images_delete on storage.objects for delete to authenticated using(bucket_id='listings' and (storage.foldername(name))[1]=auth.uid()::text and public.is_active());
commit;
